from pathlib import Path
TODAY='2026-06-18'

def header(title):
    return f'''# {title}\n\n> - 引用级别：✅可供学习参考\n> - 最后更新：{TODAY}\n\n'''

def write(path, text):
    Path(path).write_text(text.strip()+"\n", encoding='utf-8')

# helpers
risk_common = '出现持续加重、明显疼痛、意识异常、呼吸困难、出血、严重脱水、儿童老人孕妇等特殊人群症状明显时，应优先就医评估。'

def disease_article(title, path, positioning, concepts, consult, triage, categories, scenarios, analysis):
    concept_text='\n\n'.join([f"### {i+1}. {c['name']}\n\n{c['body']}" for i,c in enumerate(concepts)])
    consult_text='\n'.join(f"- {x}" for x in consult)
    triage_rows='\n'.join(f"| {a} | {b} | {c} | {d} |" for a,b,c,d in triage)
    cat_rows='\n'.join(f"| {a} | {b} | {c} |" for a,b,c in categories)
    scen_rows='\n'.join(f"| {a} | {b} | {c} |" for a,b,c in scenarios)
    analysis_text='\n'.join(f"- **{k}：** {v}" for k,v in analysis)
    text=header(title)+f'''## 一句话定位\n\n{positioning}\n\n## 一、准确解释：三个概念分别是什么\n\n{concept_text}\n\n## 二、药店咨询首先要问什么\n\n{consult_text}\n\n## 三、轻症、需药师判断、应就医的分层\n\n| 分层 | 典型表现 | 药店/平台可以做什么 | 不应做什么 |\n|---|---|---|---|\n{triage_rows}\n\n## 四、常见品类与药店咨询口径\n\n| 品类/服务 | 适合讨论的场景 | 药师提醒点 |\n|---|---|---|\n{cat_rows}\n\n## 五、即时零售医药场景拆解\n\n| 场景 | 用户需求 | 平台/药店承接点 |\n|---|---|---|\n{scen_rows}\n\n## 六、对平台、药店、药企的业务分析\n\n{analysis_text}\n'''
    write(path,text)

# 1 腹泻胃痛消化不良 full exemplar
disease_article('腹泻胃痛消化不良基础概念','08-疾病与医学基础/补充资料/腹泻胃痛消化不良基础概念.md',
'本文回答：腹泻、胃痛、消化不良分别是什么，它们在药店咨询和即时零售买药场景中如何被识别、分层和提醒就医。核心判断是：这类症状适合承接轻症对症用品、补液、家庭常备和药师咨询，但必须先区分短期轻症、特殊人群和红旗信号，不能把症状搜索直接等同为疾病诊断或用药结论。',
[
{'name':'腹泻：排便频次和性状改变，不是单一疾病','body':'腹泻通常指排便次数增多、粪便变稀或呈水样，可伴随腹痛、腹胀、恶心、呕吐、发热或乏力。它本身是症状表现，不是具体诊断。常见诱因包括饮食不洁、胃肠道感染、食物不耐受、药物影响、肠易激综合征、炎症性肠病或其他消化系统疾病。药店和即时零售场景中，腹泻最需要先区分三件事：是否短期轻症、是否有脱水风险、是否有血便高热持续剧痛等红旗信号。'},
{'name':'胃痛/上腹痛：用户常说的“胃痛”可能来自多个部位','body':'用户说“胃痛”通常指上腹部疼痛、烧灼感、胀痛、隐痛或餐前餐后不适，但不一定都来自胃。可能相关的情况包括胃酸反流、胃炎样不适、消化不良、胃肠痉挛、胆囊或胰腺相关问题，部分心血管问题也可能表现为上腹不适。因此药店咨询不能把“胃痛”直接等同为“胃病”或“需要胃药”。'},
{'name':'消化不良：一组上腹部不适症状，而不是明确诊断','body':'消化不良通常指餐后饱胀、早饱、上腹部疼痛或烧灼感，也可能伴随嗳气、恶心、反酸或食欲下降。它可以是功能性消化不良，也可能与胃食管反流、胃炎、消化性溃疡、药物刺激、幽门螺杆菌感染或其他疾病有关。平台和药店应把它理解为症状群，而不是直接对应某一种药。'},
{'name':'三者之间的关系：可以同时出现，但不能互相替代','body':'腹泻、胃痛和消化不良都属于消化系统常见症状，用户常混合表达为“拉肚子胃痛”“吃坏肚子胃不舒服”“胃胀不消化”。但三者关注点不同：腹泻先看脱水和感染风险，胃痛先看疼痛部位和严重程度，消化不良先看餐后关系、持续时间和反复程度。文章必须把症状识别、风险分层、对症用品和就医提醒分开。'}],
['询问年龄、孕产状态、基础病和免疫状态，儿童、老人、孕妇和免疫低下人群风险更高。','询问症状持续时间、频次、严重程度，以及是否影响进食、睡眠和日常活动。','询问伴随症状：发热、呕吐、血便、黑便、脱水、体重下降、吞咽困难、胸痛或持续剧痛。','询问近期饮食、旅行、可疑食物、饮酒、抗生素或止痛药等用药背景。','询问既往胃肠病史和正在使用的药物，避免重复成分或不匹配用药。'],
[('轻症自我管理','短期、轻度、无红旗信号','补液、说明书教育、药师咨询、观察症状变化','不做疾病诊断，不承诺快速治愈'),('药师重点询问','反复、持续、儿童老人、伴发热呕吐或近期特殊用药','追问病程、风险因素和用药禁忌，必要时建议就医','不直接推荐多药叠加或强行止症状'),('优先就医','血便、黑便、严重脱水、持续剧痛、高热、呕血、意识差','明确提示就医或急诊评估','不引导仅靠自购药处理')],
[('口服补液盐','腹泻、呕吐后补液和家庭常备','关注脱水、儿童老人风险，提醒按说明书配制'),('止泻相关药物','短期轻症、无红旗信号场景','发热、血便、疑似感染或特殊人群需谨慎'),('益生菌','部分腹泻或肠道菌群相关场景','不夸大疗效，注意特殊人群'),('胃酸相关OTC','反酸、烧心、上腹不适场景','黑便、呕血、吞咽困难、持续疼痛需就医'),('消化酶/助消化类','餐后饱胀、饮食相关不适','不替代持续或反复症状评估')],
[('急用','夜间腹泻、临时补液、胃部不适','附近库存、配送时效、药师在线'),('家庭常备','补液盐、益生菌、胃酸相关OTC备货','常备清单、适用人群、说明书提醒'),('咨询','用户不确定是轻症还是风险信号','药师问诊模板、红旗信号提示'),('转诊','出现血便、黑便、严重脱水、持续剧痛等','明确提示及时就医')],
[('平台','症状词入口要先做风险分层，再展示商品；腹泻、胃痛、消化不良不能直接转化为单品推荐。'),('药店','药师问诊模板比单纯SKU推荐更重要，应围绕持续时间、年龄、脱水、便血黑便、既往用药和特殊人群解释。'),('药企','适合做说明书教育、成分区分和适用人群解释，避免把症状营销等同疾病诊断。')])

