def generic_disease(title,path,topic,theme,ask,redflag):
    concepts=[
        {'name':f'{topic}：先把医学对象和用户说法分开','body':f'{topic}相关内容在平台和药店场景中常被用户用症状词、商品词或疾病词混合表达。医学基础文章首先要说明它是疾病、症状、风险因素还是用药场景，不能把用户搜索词直接当作诊断。本文关注的是{theme}，用于帮助读者建立咨询分层和场景认知。'},
        {'name':'常见表现：哪些信息能帮助初步分层','body':f'药店咨询应围绕{ask}等信息展开。常见表现只能帮助识别风险和服务需求，不能替代医生诊断。平台页面应把症状教育、说明书提醒和就医提示放在商品转化之前。'},
        {'name':'用药边界：药品选择必须服从诊断、说明书和特殊人群','body':'医学基础文章可以解释常见品类和咨询口径，但不应给出个体化治疗方案。处方药、特殊人群、长期慢病和症状加重场景，需要回到医生诊疗、药师审方和说明书要求。'},
        {'name':'即时零售关系：适合承接可得性，不适合替代判断','body':'即时零售的价值在于提升附近库存、急用药、慢病复购和药师咨询效率；但平台不能把“可以买到”写成“适合使用”，也不能把“高频搜索”写成疾病判断。'}]
    consult=['确认用户表达的是疾病名称、症状、用药需求还是复购需求。',f'重点询问：{ask}。','确认年龄、孕产状态、基础病、肝肾功能、过敏史和正在使用的药物。','确认是否出现红旗信号或症状加重。','提醒阅读说明书，避免重复用药、禁忌用药和自行停用处方药。']
    triage=[('轻症/稳定场景','症状轻、短期或已有明确诊断且按医嘱复购','说明书教育、药师咨询、常备用品或复购提醒','不做新的疾病诊断'),('需药师重点判断','症状反复、用药不清、特殊人群或多药联用','追问风险因素、核对说明书和既往用药，必要时建议就医','不简单按关键词推荐药品'),('优先就医',redflag,'提示尽快就医或联系医生','不引导仅靠自购药处理')]
    categories=[('对症/辅助品类','短期轻症、常备用品或说明书明确适用场景','核对适用人群、禁忌、不良反应和重复成分'),('处方药/长期用药','已有诊断和医嘱下的复购或依从性管理','不建议自行启停或替换，关注复诊和监测'),('药师咨询','用户不确定症状、品类或用药边界','做风险分层和就医提醒，不替代医生诊断'),('健康管理用品','监测、记录、生活方式支持','用于辅助管理，不能替代治疗')]
    scenarios=[('急用/临时不适','希望快速获得对症用品或咨询','附近库存、药师在线、红旗信号提示'),('慢病复购','已有诊断和长期用药需求','处方/医保/复诊提醒、依从性管理'),('家庭常备','提前备药或补充监测用品','常备清单、特殊人群提醒'),('就医提醒','出现红旗信号或症状加重','明确提示线下就医或急诊')]
    analysis=[('平台','应把医学分层和红旗信号嵌入搜索、问答和商品推荐，不能只按转化率排序。'),('药店','药师应围绕症状、病史、特殊人群和用药风险进行咨询，复购场景也要核对依从性和不良反应。'),('药企','适合提供说明书教育、用药依从性和适用人群解释，避免把疾病教育写成夸大疗效。')]
    disease_article(title,path,f'本文回答：{topic}是什么，在药店咨询和即时零售医药场景中如何识别、分层和提醒就医。核心判断是：{theme}可以形成即时零售的咨询、常备和复购需求，但医学基础文章必须先解释概念、风险信号和用药边界，不能把症状搜索或商品需求直接等同为诊断和用药结论。',concepts,consult,triage,categories,scenarios,analysis)

